function sideLocationUnlocked(id,worldFlags=[],defeated=[]){
 if(typeof id!=='string'||!Object.hasOwn(SIDE_LOCATIONS,id))return false;
 const spec=SIDE_LOCATIONS[id],known=worldFlags?.[spec.flagRealm??spec.realm];
 return (spec.requiresRealmBoss===false||defeated?.[spec.realm]===true)&&Array.isArray(known)&&spec.requiredFlags.every(flag=>known.includes(flag));
}
function realmRests(n){return levels[n]?[...levels[n].rests,...(n===1?[COUNCIL_TRAVEL]:n===0?[CULT_TRAVEL]:[]),...Object.values(SIDE_LOCATIONS).filter(spec=>spec.realm===n).flatMap(spec=>[...spec.map.rests,...(spec.map.checkpoints||[])])]:[];}
for(const [index,map] of levels.entries())map.progressFlags=[...(map.progressFlags||[]),BOSS_REWARDS[index].id,BOSS_REWARDS[index].claim];



/* camp-services.js */
/* Pure camp transactions. Rescue/location/UI checks remain separate concerns:
 * transact enforces rescue access; its caller must also verify proximity/state.
 * validate returns a boolean. price returns null when no next rank exists.
 * Valid input states always produce an independent state copy, even on failure;
 * malformed states produce state:null. No function mutates the supplied state. */
'use strict';
const CampServiceRules=(()=>{
 const profile=Object.freeze({rankLimit:5,weaponStep:.5,armorStep:20,weaponBuy:100,weaponSell:50,herbsPerBrew:3,brewHeal:3});
 const starters=Object.freeze(['katana','naginata','swordShield']);
 const styles=Object.freeze([...starters,'foxfireKatana']);
 const fields=Object.freeze(['ownedWeapons','weaponRank','armorRank','herbs','potions']);
 const integer=(value,min,max=Number.MAX_SAFE_INTEGER)=>Number.isSafeInteger(value)&&value>=min&&value<=max;
 const validStyle=style=>typeof style==='string'&&styles.includes(style);
 function fresh(style){
  if(!starters.includes(style))throw new TypeError('Unknown camp weapon style');
  return {ownedWeapons:[style],weaponRank:0,armorRank:0,herbs:0,potions:0};
 }
 function validate(data,equipped){
  return !!data&&typeof data==='object'&&!Array.isArray(data)&&Object.keys(data).length===fields.length&&fields.every(key=>Object.hasOwn(data,key))&&
   Array.isArray(data.ownedWeapons)&&data.ownedWeapons.length>0&&data.ownedWeapons.length<=styles.length&&
   Array.from(data.ownedWeapons).every(validStyle)&&new Set(data.ownedWeapons).size===data.ownedWeapons.length&&
   validStyle(equipped)&&data.ownedWeapons.includes(equipped)&&
   integer(data.weaponRank,0,profile.rankLimit)&&integer(data.armorRank,0,profile.rankLimit)&&
   integer(data.herbs,0)&&integer(data.potions,0);
 }
 function price(rank){return integer(rank,0,profile.rankLimit-1)?50*(rank+1):null;}
 function copy(data){return {ownedWeapons:[...data.ownedWeapons],weaponRank:data.weaponRank,armorRank:data.armorRank,herbs:data.herbs,potions:data.potions};}
 function transact(data,coins,action,context={}){
  const state=validate(data,context?.equipped)?copy(data):null;
  const fail=reason=>({ok:false,state,coins,reason});
  if(!state)return fail('invalidState');
  if(!integer(coins,0))return fail('invalidCoins');
  if(!action||typeof action!=='object'||Array.isArray(action)||!['buyWeapon','sellWeapon','forgeWeapon','forgeArmor','brew'].includes(action.type))return fail('invalidAction');
  const success=()=>({ok:true,state,coins,reason:null});
  if(action.type==='brew'){
   if(context.herbalistRescued!==true)return fail('herbalistUnavailable');
   if(state.herbs<profile.herbsPerBrew)return fail('insufficientHerbs');
   if(state.potions===Number.MAX_SAFE_INTEGER)return fail('stockOverflow');
   state.herbs-=profile.herbsPerBrew;state.potions++;return success();
  }
  if(context.smithRescued!==true)return fail('smithUnavailable');
  if(action.type==='buyWeapon'||action.type==='sellWeapon'){
   const weapon=action.weapon;
   // Relics enter ownership only through their quest reward, never commerce.
   if(!starters.includes(weapon))return fail('invalidWeapon');
   const owned=state.ownedWeapons.includes(weapon);
   if(action.type==='buyWeapon'){
    if(owned)return fail('alreadyOwned');
    if(coins<profile.weaponBuy)return fail('insufficientCoins');
    state.ownedWeapons.push(weapon);coins-=profile.weaponBuy;
   }else{
    if(!owned)return fail('notOwned');
    if(state.ownedWeapons.length===1)return fail('lastWeapon');
    if(weapon===context.equipped)return fail('equippedWeapon');
    if(coins>Number.MAX_SAFE_INTEGER-profile.weaponSell)return fail('coinOverflow');
    state.ownedWeapons=state.ownedWeapons.filter(id=>id!==weapon);coins+=profile.weaponSell;
   }
   return success();
  }
  const rank=action.type==='forgeWeapon'?'weaponRank':'armorRank',cost=price(state[rank]);
  if(cost===null)return fail('maxRank');
  if(coins<cost)return fail('insufficientCoins');
  state[rank]++;coins-=cost;return success();
 }
 return Object.freeze({profile,fresh,validate,price,transact});
})();


/* serpent-relics.js */
/* Historical scale flags are retained; the talisman consumes their held view. */
'use strict';
const SerpentRelics=(()=>{
 const result='triuneSerpentTalisman';
 const scales=Object.freeze([{id:'whiteSerpentScale',realm:0,guardian:'whiteSerpent'},{id:'serpentScale',realm:1},{id:'wingedSerpentScale',realm:2,guardian:'wingedSerpent'}].map(Object.freeze));
 const united=()=>flags[0].includes(result);
 const held=spec=>!united()&&flags[spec.realm].includes(spec.id)&&!soldItems.includes(spec.id);
 function canUnite(){return state==='campService'&&!Prologue.active&&level===mysticTent&&(DevSession.active||flags[0].includes('enchanterRescued'))&&pointNear(level.servicePoint,120,100)&&!united()&&scales.every(held);}
 function unite(){
  if(!canUnite())return false;
  flags[0].push(result);persist();updateHUD();CampWorkshop.close();
  story('camp.dialogue.label','camp.npc.enchanter.name','serpent.fusion.dialogue',()=>toast(I18n.t('serpent.fusion.complete')),{right:'enchanter',speaker:'enchanter'});
  return true;
 }
 function equip(id){
  if(state!=='inventory'||Prologue.active&&!DevSession.active||id!==null&&id!==result||id===result&&(!united()||soldItems.includes(result)))return false;
  equippedTalisman=id;persist();updateHUD();return true;
 }
 return Object.freeze({scales,result,equip,united,held,canUnite,unite,armorBonus:()=>united()&&equippedTalisman===result?20:0});
})();


/* camp-health.js */
/* Shared health presentation retains fractional damage without inventing HP. */
'use strict';
const CampHealth=(()=>{
 function number(hp){return (Math.ceil(Math.max(0,hp)*10-1e-9)/10).toLocaleString(I18n.locale,{maximumFractionDigits:1});}
 function render(node,hp,maxHp){
  if(maxHp>20){node.innerHTML='<span aria-hidden="true">♥</span><span class="health-count">'+number(hp)+' / '+number(maxHp)+'</span>';node.setAttribute('aria-label',I18n.format('message.arg0.of.arg1.health',[number(hp),number(maxHp)]));return;}
  node.innerHTML=Array.from({length:Math.ceil(maxHp)},(_,i)=>{
   const fill=Math.max(0,Math.min(1,hp-i));
   if(fill>=1)return '<span>♥</span>';
   if(fill<=0)return '<span class="empty">♥</span>';
   return '<span style="position:relative;display:inline-block"><span class="empty">♥</span><span style="position:absolute;inset:0;clip-path:inset(0 '+((1-fill)*100)+'% 0 0)">♥</span></span>';
  }).join('');
  node.setAttribute('aria-label',I18n.format('message.arg0.of.arg1.health',[number(hp),number(maxHp)]));
 }
 return Object.freeze({number,render});
})();


