  $('closeShop').textContent=I18n.t('inventory.close');$('shopStatus').textContent='';
  $('shopSell').hidden=shop.id==='cook';$('shopSell').textContent=I18n.t(shop.id==='trader'?'merchant.trader.sell':'merchant.sell.title');
