  e.animTime+=raw;e.inv=Math.max(0,e.inv-raw);e.stun=Math.max(0,e.stun-raw);e.legInv=Math.max(0,e.legInv-raw);e.healFlash=Math.max(0,e.healFlash-raw);e.walkSpeed=0;
